+                if (values.advanceExact(doc)) {
+                    List<Object> objects = new ArrayList<>();
+                    int valuesCount = values.docValueCount();
+                    long previous = Long.MAX_VALUE;
+                    for (int i = 0; i < valuesCount; ++i) {
+                        long val = values.nextValue();
+                        if (previous != val || i == 0) {
+                            objects.add(val);
