+                        if (i > 0 && previous.get().equals(bytes)) {
+                            continue;
+                        }
+                        previous.copyBytes(bytes);
+                        objects.add(BytesRef.deepCopyOf(bytes));
+                    }
+                    return objects;
+                } else {
+                    return null;
+                }
+            };
+        }
+    }
