+
+        IPTermValuesSource(ValuesSourceConfig source) {
+            super(source);
+        }
+
+        @Override
+        public InternalMultiTerms.KeyConverter keyConverter() {
+            return InternalMultiTerms.KeyConverter.IP;
+        }
+    }
